#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode held the NewObject-created UArenaScoreTracker in an unreflected raw pointer. The game mode being its Outer does not keep the tracker alive. Garbage collection could reclaim it, leaving OnGoalScored to call AddPoints through a dangling pointer. The shipping log records a purge followed by a goal and an access violation in AddPoints.",
  "no_colors_cause": "BeginPlay loads /Game/Data/Palettes/DA_Primary.DA_Primary by a string path, which does not declare a cook dependency. With bCookAll=False and no always-cook entry for /Game/Data/Palettes, the palette was missing from the packaged run. LoadObject returned null and the arena used fallback gray."
}
